from math import ceil

def solve():
    n, k = map(int, input().split())
    left, right = 0, n - 1
    ans = n
    while left <= right:
        mid = ceil(left / k) * k
        count = 0
        for i in range(left, right + 1):
            if i + mid <= right and i >= left:
                count += min(i / k, i + mid / k)
        if count >= n - count:
            ans = min(ans, count)
            left = right + 1
        else:
            right = left - 1
    print(ans)

