import heapq

def solve():
    for _ in range(int(input())):
        n = int(input())
        p = []
        for _ in range(n):
            x, y = map(int, input().split())
            p.append([x, y])

        p.sort()
        q = []
        for i in range(1, n):
            q.append(p[i - 1])
            heapq.heappush(q, (p[i][1], p[i][0]))
        while q:
            u, v = heapq.heappop(q)
            if u > v:
                q.append((v, v))
            else:
                heapq.heappush(q, (u, v))
        print(sum(q))

